const proc = global.get('process') || {};
msg.statusCode = 200;
msg.headers = {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*'
};
msg.payload = {
    status: 'healthy',
    service: 'FlowField',
    framework: 'REGENOVA (incorporating REAMP Engine Architecture)',
    version: '0.1.0',
    uptime_seconds: proc.uptime ? Math.floor(proc.uptime()) : 0,
    memory_usage_mb: (proc.memoryUsage && proc.memoryUsage()) ? Math.round(proc.memoryUsage().rss / (1024 * 1024)) : 0,
    timestamp: new Date().toISOString()
};
return msg;

msg.statusCode = 200;
msg.headers = {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*'
};
msg.payload = {
    status: 'ready',
    service: 'FlowField',
    subsystem_checks: {
        runtime: 'OK',
        event_loop: 'OK'
    },
    timestamp: new Date().toISOString()
};
return msg;

msg.statusCode = 200;
msg.headers = {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*'
};
msg.payload = {
    service: 'REGENOVA FlowField — IoT Integration, Telemetry & Event Flow Service',
