        '/api/v1/telemetry/ingest'
    ],
    integrated_services: {
        platform: 'https://regenova.cloud/',
        api: 'https://api.regenova.cloud/',
        backoffice: 'https://backoffice.regenova.cloud/',
        twinfield: 'https://twinfield.regenova.cloud/'
    },
    timestamp: new Date().toISOString()
};
return msg;
